script:
frappe.ui.form.on('Daily Subsistence Allowance', {
    accomo_not_paid_costs(frm) { calculate_dsa_total(frm); },
    accomo_paid_costs(frm) { calculate_dsa_total(frm); },
    travel_ticket_costs(frm) { calculate_dsa_total(frm); },
    receipt_claim(frm) { calculate_dsa_total(frm); },
    meal_allowance(frm) { calculate_dsa_total(frm); },
    cost_of_accomo(frm) { calculate_dsa_total(frm); },
    fuel_refund_costs(frm) { calculate_dsa_total(frm); }
});

function calculate_dsa_total(frm) {
    // Fetches each field value, defaulting to 0 if empty
    let acc_not_paid = frm.doc.accomo_not_paid_costs || 0;
    let acc_paid = frm.doc.accomo_paid_costs || 0;
    let ticket = frm.doc.travel_ticket_costs || 0;
    let receipt = frm.doc.receipt_claim || 0;
    let meal = frm.doc.meal_allowance || 0;
    let cost_acc = frm.doc.cost_of_accomo || 0;
    let fuel = frm.doc.fuel_refund_costs || 0;

    // Calculates the total sum of fields 2 through 8
    let total = acc_not_paid + acc_paid + ticket + receipt + meal + cost_acc + fuel;

    // Sets the calculated sum into your target field
    frm.set_value('dsa_costs_total', total);
}
